public enum EngineError: Swift.Error {

    
    
    /**
     * The query text could not be parsed (unbalanced quotes or parentheses…).
     */
    case Query(message: String
    )
    /**
     * The index was built with another schema or normalization version.
     */
    case Rebuild(message: String
    )
    case Index(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEngineError: FfiConverterRustBuffer {
    typealias SwiftType = EngineError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EngineError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Query(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Rebuild(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Index(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EngineError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Query(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Rebuild(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Index(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
